pub fn s_agent_slot_status(p: &mut Payload) {
    parse(p);
    fn parse(p: &mut Payload) {
        let Some(Value::Object(input)) = &p.value else {
            p.push(invalid_type("object", p.value.as_ref(), None));
            return;
        };
        let input = input.clone();
        let mut out = serde_json::Map::new();
        property(p, &mut out, &input, "type", s_agent_slot_status__type, OptIn::Required, false);
        property(p, &mut out, &input, "slot_id", s_slot_id, OptIn::Required, false);
        property(p, &mut out, &input, "state", s_slot_state, OptIn::Required, false);
        property(p, &mut out, &input, "allocation_id", s_agent_slot_status__allocation_id, OptIn::Required, false);
        property(p, &mut out, &input, "match_id", s_agent_slot_status__match_id, OptIn::Required, false);
        property(p, &mut out, &input, "plugin_online", s_agent_slot_status__plugin_online, OptIn::Required, false);
        property(p, &mut out, &input, "gslt_state", s_gslt_state, OptIn::Required, false);
        property(p, &mut out, &input, "reserved", s_agent_slot_status__reserved, OptIn::Required, false);
        property(p, &mut out, &input, "server_steam_id", s_agent_slot_status__server_steam_id, OptIn::Required, false);
        p.value = Some(Value::Object(out));
    }
    let mut stopped = aborted(p, 0);
    if !stopped {
        let start = p.issues.len();
        let value = p.value.clone().unwrap_or(Value::Null);
        crate::refine::agent_slot_status(&value, &mut RefineCtx::new(p));
        if p.issues.len() != start {
            stopped = aborted(p, start);
        }
    }
    let _ = stopped;
}

