pub fn s_controller_host(p: &mut Payload) {
    if !matches!(p.value, Some(Value::String(_))) {
        p.push(invalid_type("string", p.value.as_ref(), None));
    }
    let mut stopped = aborted(p, 0);
    if !stopped {
        let start = p.issues.len();
        if !crate::refine::controller_host(p.value.as_ref().unwrap_or(&Value::Null)) {
            p.push(Issue::new(
                Code::Custom,
                "must be a host with an optional port and no scheme or path, e.g. cs.example.com, 192.168.0.10:3000 or [fd00::1]",
                Some(true),
            ));
        }
        if p.issues.len() != start {
            stopped = aborted(p, start);
        }
    }
    let _ = stopped;
}

pub fn s_controller_path(p: &mut Payload) {
    if !matches!(p.value, Some(Value::String(_))) {
        p.push(invalid_type("string", p.value.as_ref(), None));
    }
    let mut stopped = aborted(p, 0);
    {
        let start = p.issues.len();
        check_max_length(
            p,
            255,
            &LengthMessages { string: "Too big: expected string to have <=255 characters", array: "Too big: expected array to have <=255 items" },
            false,
        );
        if !stopped && p.issues.len() != start {
            stopped = aborted(p, start);
        }
    }
    if !stopped {
        let start = p.issues.len();
        check_pattern(p, &RE_4, "must be a path starting with /, without a query, fragment or spaces", false);
        if p.issues.len() != start {
            stopped = aborted(p, start);
        }
    }
    let _ = stopped;
}

