pub fn s_controller_to_agent_message(p: &mut Payload) {
    if !matches!(p.value, Some(Value::Object(_))) {
        p.push(invalid_type("object", p.value.as_ref(), None));
        return;
    }
    let tag = p.value.as_ref().and_then(|value| value.get("type")).cloned();
    if same(tag.as_ref(), &json!("start_server")) {
        s_controller_start_server(p);
    } else if same(tag.as_ref(), &json!("stop_server")) {
        s_controller_stop_server(p);
    } else if same(tag.as_ref(), &json!("get_server_status")) {
        s_controller_get_server_status(p);
    } else if same(tag.as_ref(), &json!("update_cs2")) {
        s_controller_update_cs2(p);
    } else if same(tag.as_ref(), &json!("check_cs2_build")) {
        s_controller_check_cs2_build(p);
    } else if same(tag.as_ref(), &json!("delete_demo")) {
        s_controller_delete_demo(p);
    } else if same(tag.as_ref(), &json!("reserve_slot")) {
        s_controller_reserve_slot(p);
    } else if same(tag.as_ref(), &json!("set_config")) {
        s_controller_set_config(p);
    } else if same(tag.as_ref(), &json!("update_agent")) {
        s_controller_update_agent(p);
    } else if same(tag.as_ref(), &json!("update_cs2_image")) {
        s_controller_update_cs2_image(p);
    } else if same(tag.as_ref(), &json!("watch_resources")) {
        s_controller_watch_resources(p);
    } else if same(tag.as_ref(), &json!("watch_logs")) {
        s_controller_watch_logs(p);
    } else if same(tag.as_ref(), &json!("welcome")) {
        s_controller_welcome(p);
    } else if same(tag.as_ref(), &json!("hello_refused")) {
        s_controller_hello_refused(p);
    } else if same(tag.as_ref(), &json!("console_command")) {
        s_controller_console_command(p);
    } else if same(tag.as_ref(), &json!("restore_round")) {
        s_controller_restore_round(p);
    } else if same(tag.as_ref(), &json!("start_match")) {
        s_controller_start_match(p);
    } else {
        let mut issue = Issue::new(
            Code::InvalidUnion,
            "Invalid discriminator value. Expected 'start_server' | 'stop_server' | 'get_server_status' | 'update_cs2' | 'check_cs2_build' | 'delete_demo' | 'reserve_slot' | 'set_config' | 'update_agent' | 'update_cs2_image' | 'watch_resources' | 'watch_logs' | 'welcome' | 'hello_refused' | 'console_command' | 'restore_round' | 'start_match'",
            None,
        );
        issue.path = vec![PathKey::key("type")];
        p.push(issue);
    }
}

