pub fn s_log_source(p: &mut Payload) {
    if !matches!(p.value, Some(Value::Object(_))) {
        p.push(invalid_type("object", p.value.as_ref(), None));
        return;
    }
    let tag = p.value.as_ref().and_then(|value| value.get("kind")).cloned();
    if same(tag.as_ref(), &json!("agent")) {
        s_log_source__0(p);
    } else if same(tag.as_ref(), &json!("cs2_update")) {
        s_log_source__1(p);
    } else if same(tag.as_ref(), &json!("server")) {
        s_log_source__2(p);
    } else {
        let mut issue = Issue::new(Code::InvalidUnion, "Invalid discriminator value. Expected 'agent' | 'cs2_update' | 'server'", None);
        issue.path = vec![PathKey::key("kind")];
        p.push(issue);
    }
}

