pub fn s_player_name(p: &mut Payload) {
    if !matches!(p.value, Some(Value::String(_))) {
        p.push(invalid_type("string", p.value.as_ref(), None));
    }
    let mut stopped = aborted(p, 0);
    {
        let start = p.issues.len();
        check_max_length(
            p,
            64,
            &LengthMessages { string: "Too big: expected string to have <=64 characters", array: "Too big: expected array to have <=64 items" },
            false,
        );
        if !stopped && p.issues.len() != start {
            stopped = aborted(p, start);
        }
    }
    if !stopped {
        let start = p.issues.len();
        if !crate::refine::clean_text(p.value.as_ref().unwrap_or(&Value::Null)) {
            p.push(Issue::new(Code::Custom, "must be text without NUL or lone surrogates", Some(true)));
        }
        if p.issues.len() != start {
            stopped = aborted(p, start);
        }
    }
    if !stopped {
        let start = p.issues.len();
        check_pattern(p, &RE_13, "must not contain control characters", false);
        if p.issues.len() != start {
            stopped = aborted(p, start);
        }
    }
    let _ = stopped;
}

