pub fn s_plugin_to_controller_message(p: &mut Payload) {
    if !matches!(p.value, Some(Value::Object(_))) {
        p.push(invalid_type("object", p.value.as_ref(), None));
        return;
    }
    let tag = p.value.as_ref().and_then(|value| value.get("type")).cloned();
    if same(tag.as_ref(), &json!("map_start")) {
        s_map_start(p);
    } else if same(tag.as_ref(), &json!("player_connect")) {
        s_player_connect(p);
    } else if same(tag.as_ref(), &json!("player_disconnect")) {
        s_player_disconnect(p);
    } else if same(tag.as_ref(), &json!("knife_start")) {
        s_knife_start(p);
    } else if same(tag.as_ref(), &json!("knife_end")) {
        s_knife_end(p);
    } else if same(tag.as_ref(), &json!("side_choice")) {
        s_side_choice(p);
    } else if same(tag.as_ref(), &json!("going_live")) {
        s_going_live(p);
    } else if same(tag.as_ref(), &json!("round_backup")) {
        s_round_backup(p);
    } else if same(tag.as_ref(), &json!("match_restored")) {
        s_match_restored(p);
    } else if same(tag.as_ref(), &json!("round_start")) {
        s_round_start(p);
    } else if same(tag.as_ref(), &json!("round_freeze_end")) {
        s_round_freeze_end(p);
    } else if same(tag.as_ref(), &json!("round_buy_end")) {
        s_round_buy_end(p);
    } else if same(tag.as_ref(), &json!("round_end")) {
        s_round_end(p);
    } else if same(tag.as_ref(), &json!("round_complete")) {
        s_round_complete(p);
    } else if same(tag.as_ref(), &json!("player_death")) {
        s_player_death(p);
    } else if same(tag.as_ref(), &json!("player_hurt")) {
        s_player_hurt(p);
    } else if same(tag.as_ref(), &json!("player_blind")) {
        s_player_blind(p);
    } else if same(tag.as_ref(), &json!("grenade_throw")) {
        s_grenade_throw(p);
    } else if same(tag.as_ref(), &json!("grenade_detonate")) {
        s_grenade_detonate(p);
    } else if same(tag.as_ref(), &json!("grenade_end")) {
        s_grenade_end(p);
    } else if same(tag.as_ref(), &json!("round_shots")) {
        s_round_shots(p);
    } else if same(tag.as_ref(), &json!("bomb_begin_plant")) {
        s_bomb_begin_plant(p);
    } else if same(tag.as_ref(), &json!("bomb_abort_plant")) {
        s_bomb_abort_plant(p);
    } else if same(tag.as_ref(), &json!("bomb_planted")) {
        s_bomb_planted(p);
    } else if same(tag.as_ref(), &json!("bomb_begin_defuse")) {
        s_bomb_begin_defuse(p);
    } else if same(tag.as_ref(), &json!("bomb_abort_defuse")) {
        s_bomb_abort_defuse(p);
    } else if same(tag.as_ref(), &json!("bomb_defused")) {
        s_bomb_defused(p);
    } else if same(tag.as_ref(), &json!("bomb_exploded")) {
        s_bomb_exploded(p);
    } else if same(tag.as_ref(), &json!("round_mvp")) {
        s_round_mvp(p);
    } else if same(tag.as_ref(), &json!("map_end")) {
        s_map_end(p);
    } else if same(tag.as_ref(), &json!("log")) {
        s_plugin_log(p);
    } else {
        let mut issue = Issue::new(
            Code::InvalidUnion,
            "Invalid discriminator value. Expected 'map_start' | 'player_connect' | 'player_disconnect' | 'knife_start' | 'knife_end' | 'side_choice' | 'going_live' | 'round_backup' | 'match_restored' | 'round_start' | 'round_freeze_end' | 'round_buy_end' | 'round_end' | 'round_complete' | 'player_death' | 'player_hurt' | 'player_blind' | 'grenade_throw' | 'grenade_detonate' | 'grenade_end' | 'round_shots' | 'bomb_begin_plant' | 'bomb_abort_plant' | 'bomb_planted' | 'bomb_begin_defuse' | 'bomb_abort_defuse' | 'bomb_defused' | 'bomb_exploded' | 'round_mvp' | 'map_end' | 'log'",
            None,
        );
        issue.path = vec![PathKey::key("type")];
        p.push(issue);
    }
}

pub fn s_port(p: &mut Payload) {
    if !matches!(p.value, Some(Value::Number(_))) {
        p.push(invalid_type("number", p.value.as_ref(), None));
    }
    let mut stopped = aborted(p, 0);
    if !stopped {
        let start = p.issues.len();
        check_safeint(
            p,
            "Invalid input: expected int, received number",
            "Too big: expected int to be <=9007199254740991",
            "Too small: expected int to be >=-9007199254740991",
            false,
        );
        if p.issues.len() != start {
            stopped = aborted(p, start);
        }
    }
    if !stopped {
        let start = p.issues.len();
        check_bound(p, 1.0, true, true, "Too small: expected number to be >=1", false);
        if p.issues.len() != start {
            stopped = aborted(p, start);
        }
    }
    if !stopped {
        let start = p.issues.len();
        check_bound(p, 65535.0, true, false, "Too big: expected number to be <=65535", false);
        if p.issues.len() != start {
            stopped = aborted(p, start);
        }
    }
    let _ = stopped;
}

